import json
import numpy as np

words = open('names.txt').read().splitlines()
perm = np.random.default_rng(42).permutation(len(words))
dev = [words[i] for i in perm[25626:28829]]
test = [words[i] for i in perm[28829:]]
INDEX = {c: i for i, c in enumerate(".abcdefghijklmnopqrstuvwxyz")}


def build_dataset(ws, block=3):
    X, Y = [], []
    for w in ws:
        context = [0] * block
        for ch in w + ".":
            X.append(context)
            Y.append(INDEX[ch])
            context = context[1:] + [INDEX[ch]]
    return np.array(X), np.array(Y)


def mlp_forward(params, X):
    E = params["C"][X].reshape(X.shape[0], -1)
    h = np.tanh(E @ params["W1"] + params["b1"])
    return h @ params["W2"] + params["b2"]


trained = {k: np.array(v) for k, v in json.load(open('makemore-mlp.json')).items() if k != 'about'}
Xdev, Ydev = build_dataset(dev)
Xtest, Ytest = build_dataset(test)
P0 = {"C": np.array([[0.0], [1.0], [-1.0]]), "W1": np.array([[0.5, -1.0], [1.0, 0.5]]), "b1": np.array([0.0, 0.1]), "W2": np.array([[1.0, -1.0, 0.0], [0.5, 0.0, 2.0]]), "b2": np.array([0.0, 0.0, 0.2])}

